-- 005: server-generated primary keys.
--
-- 001 and 003 declare every `id` as `UUID PRIMARY KEY` with no default, and the
-- API never supplies one: `insert_tenant_scoped_row` (app/services/tenant_scope.py)
-- sends only the validated payload plus the server-derived organization_id.
-- Against a real database every create endpoint therefore failed with
--   23502 null value in column "id" ... violates not-null constraint
-- (found by P0-01 end-to-end verification; the unit-test fake assigned ids
-- itself and hid the defect).
--
-- The id is generated by the database, never accepted from the client: every
-- create request model sets `extra="forbid"` and none declares `id`.
--
-- gen_random_uuid() is built into PostgreSQL 13+, so no extension is required.
--
-- Forward-only. Changes defaults only; no rows, policies, grants or types change.
--
-- ROLLBACK (restores the exact pre-005 schema; creates fail again afterwards):
--   ALTER TABLE public.<table> ALTER COLUMN id DROP DEFAULT;   -- for each table below

ALTER TABLE public.organizations        ALTER COLUMN id SET DEFAULT gen_random_uuid();
ALTER TABLE public.schools              ALTER COLUMN id SET DEFAULT gen_random_uuid();
ALTER TABLE public.users                ALTER COLUMN id SET DEFAULT gen_random_uuid();
ALTER TABLE public.students             ALTER COLUMN id SET DEFAULT gen_random_uuid();
ALTER TABLE public.assessments          ALTER COLUMN id SET DEFAULT gen_random_uuid();
ALTER TABLE public.ai_recommendations   ALTER COLUMN id SET DEFAULT gen_random_uuid();
ALTER TABLE public.intervention_plans   ALTER COLUMN id SET DEFAULT gen_random_uuid();
ALTER TABLE public.intervention_actions ALTER COLUMN id SET DEFAULT gen_random_uuid();
ALTER TABLE public.progress_events      ALTER COLUMN id SET DEFAULT gen_random_uuid();
ALTER TABLE public.audit_logs           ALTER COLUMN id SET DEFAULT gen_random_uuid();
ALTER TABLE public.assessment_results   ALTER COLUMN id SET DEFAULT gen_random_uuid();
